class Solution {
    int countNodes(TreeNode* node) {
        if (!node) return 0;
        return 1 + countNodes(node->left) + countNodes(node->right);
    }
    bool check(TreeNode* node, long long idx, int n) {
        if (!node) return true;
        if (idx > n) return false;
        return check(node->left, 2 * idx, n) && check(node->right, 2 * idx + 1, n);
    }
public:
    bool isCompleteTree(TreeNode* root) {
        int n = countNodes(root);
        return check(root, 1LL, n);
    }
};
